var first = Task.FromException<int>(new InvalidOperationException());
var second = new TaskCompletionSource<int>();
var winner = await Task.WhenAny(first, second.Task);
Console.Write(winner.Status);
try
{
    _ = await winner;
}
catch (InvalidOperationException)
{
    Console.Write(", caught");
}

var canceled = Task.FromCanceled(new CancellationToken(true));
var failed = Task.FromException(new InvalidOperationException());
var batch = Task.WhenAll(canceled, failed);
Console.Write(batch.Status);

using var request = new CancellationTokenSource();
using var shutdown = new CancellationTokenSource();
using var operation = CancellationTokenSource.CreateLinkedTokenSource(request.Token, shutdown.Token);
operation.Cancel();
Console.Write((request.IsCancellationRequested, shutdown.IsCancellationRequested, operation.IsCancellationRequested));

using var slots = new SemaphoreSlim(0, 1);
var acquired = await slots.WaitAsync(TimeSpan.Zero);
Console.Write((acquired, slots.CurrentCount));
